/* Same-origin client for the host management API, polling helpers, and the panel's shared React contexts.
   The live panel reads everything through the engine's own endpoints (32-live-model); the provider therefore
   only owns transport, routing helpers and the toast — it no longer polls a global `state` document. */

import { API } from "./util.js"
import { PANEL_CSS } from "./style.js"
import { errorText } from "./i18n.js"
import { React, createContext, h, useCallback, useContext, useEffect, useMemo, useRef, useState } from "./react.js"
export class ApiError extends Error {
  constructor(message, status, details = {}) { super(message); this.status = status; this.details = details }
  get issues() { return this.details.issues ?? [] }
  get missing() { return this.status === 404 && !this.details.unreachable }
}

/* A request that never answers used to hang the polling queue forever: no error, no next attempt, the page frozen on
   the last document. Reads give up after 20s, writes after 2 minutes; a route that legitimately runs for minutes
   (running gates, a waited-for run) passes `timeoutMs: 0` instead of being cut off mid-commit. */
const READ_TIMEOUT_MS = 20000
const WRITE_TIMEOUT_MS = 120000

/** Call one management endpoint; every request is marked so the host can refuse cross-site posts. */
export async function apiCall(t, path, method, body, options = {}) {
  const timeoutMs = options.timeoutMs ?? (method === 'GET' ? READ_TIMEOUT_MS : WRITE_TIMEOUT_MS)
  const controller = timeoutMs > 0 && typeof AbortController === 'function' ? new AbortController() : undefined
  const timer = controller ? setTimeout(() => controller.abort(), timeoutMs) : undefined
  const timeoutError = () => new ApiError(t('requestTimeout', { seconds: Math.round(timeoutMs / 1000) }), 0,
    { unreachable: true, timeout: true })
  let response
  try {
    response = await fetch(`${API}/${path}`, { method, headers: { 'x-superagent-request': '1', ...body === undefined ? {} : { 'content-type': 'application/json' } },
      ...controller ? { signal: controller.signal } : {},
      body: body === undefined ? undefined : JSON.stringify(body) })
  } catch {
    clearTimeout(timer)
    throw controller?.signal.aborted ? timeoutError() : new ApiError(t('offline'), 0, { unreachable: true })
  }
  // The clock must cover the body too: clearing it once headers arrive let a stalled response hang the poll queue
  // forever, so every page kept its last data and the write button stayed busy (review P2).
  let text
  try {
    text = await response.text()
  } catch (error) {
    if (controller?.signal.aborted) throw timeoutError()
    throw error instanceof Error ? new ApiError(error.message, 0, { unreachable: true }) : new ApiError(t('offline'), 0, { unreachable: true })
  } finally {
    clearTimeout(timer)
  }
  let value
  try { value = text ? JSON.parse(text) : {} } catch { value = undefined }
  if (!response.ok) {
    const failure = value ?? {}
    const issues = Array.isArray(failure.issues) ? failure.issues : []
    const message = typeof failure.error === 'string' ? failure.error
      : !text && response.status === 404 ? t('hostNotRunning')
      : response.status >= 500 ? t('serverError', { status: response.status })
      : t('requestFailed', { status: response.status })
    // The host puts a machine-readable `code` (and bot `problems`) beside `error`; keep them for callers that must
    // show the error code next to the human sentence (worker-bots spec §13.2).
    throw new ApiError(message, response.status, { ...failure, issues, ...text ? {} : { unreachable: true } })
  }
  return value
}

/** Build the typed route caller used by every view: `call('GET engine/ticket/:id', { id })`. */
export function caller(t) {
  return (route, ...rest) => {
    const [method, pattern] = route.split(' ')
    const request = rest[0] ?? {}
    const path = pattern.replace(/:(\w+)/g, (_match, name) => encodeURIComponent(String(request[name])))
    const query = Object.entries(request.query ?? {}).filter(([, value]) => value !== undefined && value !== '')
      .map(([name, value]) => `${name}=${encodeURIComponent(String(value))}`).join('&')
    return apiCall(t, query ? `${path}?${query}` : path, method, request.body, { timeoutMs: request.timeoutMs })
  }
}

export const HIDDEN_FACTOR = 6
export const same = (a, b) => a === b || JSON.stringify(a) === JSON.stringify(b)
/** Poll one endpoint while mounted, backing off while the document is hidden and keeping the last good value. */
export function usePoll(load, deps, intervalMs = 5000) {
  const [state, setState] = useState({})
  const loader = useRef(load)
  loader.current = load
  const refresh = useRef(async () => {})
  useEffect(() => {
    let active = true
    let timer
    let queue = Promise.resolve()
    // New deps mean "different page of data": the previous document must not stay on screen while the new one loads
    // (it also kept the old error alive, so a working id could open showing the last id's failure).
    setState(previous => (previous.data === undefined && previous.error === undefined ? previous : {}))
    const once = async () => {
      clearTimeout(timer)
      try {
        const value = await loader.current()
        if (active) setState(previous => same(previous.data, value) ? (previous.error ? { data: previous.data } : previous) : { data: value })
      } catch (failure) {
        if (active) setState(previous => ({ ...previous, error: failure instanceof Error ? failure : new Error(String(failure)) }))
      } finally {
        if (active) timer = setTimeout(run, document.hidden ? intervalMs * HIDDEN_FACTOR : intervalMs)
      }
    }
    const run = () => (queue = queue.then(once))
    const shown = () => { if (!document.hidden) void run() }
    refresh.current = run
    void run()
    document.addEventListener('visibilitychange', shown)
    return () => { active = false; clearTimeout(timer); document.removeEventListener('visibilitychange', shown) }
  }, [...deps, intervalMs])
  const reload = useCallback(() => refresh.current(), [])
  return { data: state.data, error: state.error, reload }
}

/** Panel context: transport, router helpers and the shared toast; page data lives in PanelState (32-live-model). */
export const Panel = createContext(undefined)
export const PanelState = createContext(undefined)
export function usePanel() {
  const value = useContext(Panel)
  if (!value) throw new Error('Superagent panel rendered outside its provider')
  return value
}
export function usePanelData() {
  const value = useContext(PanelState)
  if (!value) throw new Error('Superagent panel rendered outside its provider')
  return value
}
/** Wrap an async action with re-entrancy protection, busy state, optional reload, and a toast on failure. */
export function useAction(action, options = {}) {
  const { notify } = usePanel()
  const [busy, setBusy] = useState(false)
  const running = useRef(false)
  const run = async (...args) => {
    if (running.current) return false
    running.current = true
    setBusy(true)
    // A handler that resolves `false` has refused the action (it already notified): the dialog stays open, exactly as
    // it does when the handler throws. Without this the confirm closed on a failed host call that did not throw.
    try {
      const result = await action(...args)
      if (result === false) return false
      // The action has committed at this point. A refresh that fails afterwards is a stale-screen problem, not a
      // failed action: reporting it as one kept a confirm dialog open on an already-applied pause/delete (review P2).
      try { await options.reload?.() } catch (failure) { notify(errorText(failure)) }
      return true
    } catch (failure) { notify(errorText(failure)); return false }
    finally { running.current = false; setBusy(false) }
  }
  return { run, busy }
}

export function Toast({ text, tone, toastKey, onDone, holdMs = 4000 }) {
  const done = useRef(onDone)
  done.current = onDone
  useEffect(() => { const timer = setTimeout(() => done.current(), holdMs + 1000); return () => clearTimeout(timer) }, [toastKey, holdMs])
  const failed = tone === 'error'
  return h('div', { className: failed ? 'sa-toast sa-toast-error' : 'sa-toast', role: failed ? 'alert' : 'status' }, text)
}

export const stay = () => {}
export const noSession = async () => {}
/** The GUI Session the panel is shown in; a host that cannot name one still loads the panel (see `currentSessionId`). */
export const noSessionId = () => ''
/** The Host terminal model for one terminal id; a host without terminal views answers undefined. */
export const noTerminalView = () => undefined
/**
 * One provider for the whole panel: the typed caller, routing callbacks, session opener and the toast.
 * `route` is passed down as well so a page can tell a list view from a deep-linked detail view.
 */
export function PanelProvider({ t, openSession = noSession, currentSessionId = noSessionId, terminalView = noTerminalView,
  navigate = stay, back = stay, backLabel = '', route, children }) {
  const copy = useRef(t)
  copy.current = t
  const call = useMemo(() => caller(key => copy.current(key)), [])
  const [toast, setToast] = useState()
  // `tone` was accepted and dropped by callers (`notify(errorText(failure), 'error')`), so a failed save and a saved
  // save looked the same. A failure now keeps the message on screen as an alert with the danger colour.
  // Monotonic, not Date.now(): two notifies in the same millisecond shared a React key, so the second toast inherited
  // the first one's dismiss timer and could vanish early.
  const toastSeq = useRef(0)
  const notify = useCallback((text, tone) => setToast({ text, tone, id: (toastSeq.current += 1) }), [])
  const context = useMemo(() => ({ t, call, navigate, back, backLabel, openSession, notify, route, currentSessionId,
    terminalView }),
  [t, call, navigate, back, backLabel, openSession, notify, route, currentSessionId, terminalView])
  return h(Panel.Provider, { value: context },
    h('style', null, PANEL_CSS),
    children,
    toast && h(Toast, { key: toast.id, toastKey: toast.id, text: toast.text, tone: toast.tone,
      onDone: () => setToast(undefined) }))
}
